//! Language bindings for sigillum.
//!
//! This crate will expose the sigillum API to Kotlin and Swift through UniFFI and to
//! JavaScript through `wasm-bindgen`. It is the only crate in the workspace where
//! `unsafe` code, generated by the binding tools, may appear.

// Generated binding code may require `unsafe`; the workspace denies it elsewhere and
// every other crate forbids it outright.
#![allow(unsafe_code)]
